const parsed = JSON.parse($json.output);

return [
  {
    json: parsed
  }
];

let output = $input.first().json.output || "";

output = output.trim();

// Remove markdown code fences if present
output = output
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

// Find the JSON object
const start = output.indexOf("{");
const end = output.lastIndexOf("}");

if (start === -1 || end === -1) {
  throw new Error("No valid JSON object found in AI output");
}

// Extract only the JSON portion
const jsonText = output.slice(start, end + 1);

const parsed = JSON.parse(jsonText);

return [
  {
    json: parsed
  }
];

// Get all 10 business-rule items
const rules = $input.all();

// Get the service information from the Prices node
const priceData = $('Prices').first().json;

return [
  {
    json: {
      service_id: priceData.service_id,
      service_name: priceData.service_name,
      starting_price_npr: priceData.starting_price_npr,

      business_rules: rules.map(item => ({
        rule_id: item.json.rule_id,
        rule_area: item.json.rule_area,
        rule_description: item.json.rule_description,
        severity: item.json.severity
      }))
    }
  }
];

const data = JSON.parse($json.output);

return [
  {
    json: data
  }
];

const sections = $input.all();

return [
  {
    json: {
      sections: sections.map(item => item.json)
    }
  }
];

const text = $input.first().json.output || "";

const cleanedText = text
  .replace(/\\n/g, "\n")
  .replace(/\r/g, "")
  .trim();

const lines = cleanedText.split("\n");

// First line = **Proposal Title**
// Second non-empty line = actual proposal title
let titleIndex = -1;
let proposalTitle = "";

for (let i = 0; i < lines.length; i++) {
  if (lines[i].trim() === "**Proposal Title**") {
    titleIndex = i;

    for (let j = i + 1; j < lines.length; j++) {
      if (lines[j].trim() !== "") {
        proposalTitle = lines[j]
          .trim()
          .replace(/^"|"$/g, "")
          .trim();

        break;
      }
    }

    break;
  }
}

// Proposal starts after the title
let proposal = lines
  .slice(titleIndex + 2)
  .join("\n")
  .trim();

return [
  {
    json: {
      proposal_title: proposalTitle,
      proposal: proposal
    }
  }
];

const data = JSON.parse($json.output);

data.errors = Array.isArray(data.errors) ? data.errors.length : data.errors;
data.warnings = Array.isArray(data.warnings) ? data.warnings.length : data.warnings;
data.required_changes = Array.isArray(data.required_changes)
  ? data.required_changes.length
  : data.required_changes;

return [
  {
    json: data
  }
];
